<?php
require_once 'config.php';login_required();
if($_SERVER['REQUEST_METHOD']==='POST'){role_required(['admin','dosen']);try{$file=upload_file('file','materi',['pdf','ppt','pptx','doc','docx','xls','xlsx','zip'],20);if(!$file)throw new Exception('Pilih file materi.');$pdo->prepare("INSERT INTO materi(mata_kuliah_id,dosen_id,judul,deskripsi,file) VALUES(?,?,?,?,?)")->execute([$_POST['mk'],user()['id'],trim($_POST['judul']),trim($_POST['deskripsi']),$file]);flash('Materi berhasil diunggah.');redirect('materi.php');}catch(Throwable $e){$error=$e->getMessage();}}
$rows=$pdo->query("SELECT ma.*,m.nama AS matkul,u.nama AS dosen FROM materi ma JOIN mata_kuliah m ON m.id=ma.mata_kuliah_id JOIN users u ON u.id=ma.dosen_id ORDER BY ma.created_at DESC")->fetchAll();$mks=$pdo->query("SELECT id,nama FROM mata_kuliah")->fetchAll();$page_title='Materi';require 'includes/header.php'; ?>
<div class="row g-4"><div class="col-lg-8"><h3>Materi perkuliahan</h3><p class="muted">Unduh modul, slide presentasi, dan bahan belajar.</p><div class="row g-3"><?php foreach($rows as $r): ?><div class="col-md-6"><div class="card-item"><div class="d-flex justify-content-between"><span class="badge badge-soft"><?= e($r['matkul']) ?></span><i class="bi bi-file-earmark-arrow-down stat-icon"></i></div><h5 class="mt-3"><?= e($r['judul']) ?></h5><p class="muted small"><?= e($r['deskripsi']) ?></p><div class="muted small mb-3">Oleh <?= e($r['dosen']) ?> · <?= date('d M Y',strtotime($r['created_at'])) ?></div><a class="btn btn-sm btn-outline-light" href="uploads/<?= e($r['file']) ?>" download>Unduh materi</a></div></div><?php endforeach; ?><?php if(!$rows): ?><p class="muted">Belum ada materi diunggah.</p><?php endif; ?></div></div>
<?php if(in_array(user()['role'],['admin','dosen'])): ?><div class="col-lg-4"><div class="form-card"><h4>Upload materi</h4><?php if(!empty($error)): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif; ?><form method="post" enctype="multipart/form-data" class="d-grid gap-3"><select name="mk" class="form-select" required><option value="">Mata kuliah</option><?php foreach($mks as $m): ?><option value="<?= $m['id'] ?>"><?= e($m['nama']) ?></option><?php endforeach; ?></select><input name="judul" class="form-control" placeholder="Judul materi" required><textarea name="deskripsi" class="form-control" placeholder="Deskripsi"></textarea><input type="file" name="file" class="form-control" required><small class="muted">PDF, PPT, DOC, XLS, ZIP · maks. 20 MB</small><button class="btn btn-primary">Upload materi</button></form></div></div><?php endif; ?></div>
<?php require 'includes/footer.php'; ?>